review:
{
  "spec": "This change extends the Todo app to support optional due dates (YYYY-MM-DD) and task completion status. The `add` command gains a `--due` flag, and the `Task` model updates to include `due_date` and `done` fields. Storage handles backward compatibility for old JSON files lacking these fields. New CLI commands `done` and `overdue` allow marking tasks complete and filtering incomplete past-due tasks. The `list` command renders due dates next to task text when present.",
  "stack": "Python, json, argparse, datetime, pytest",
  "tasks": [
    {
      "id": 1,
      "title": "Update Task model to support due dates and done status",
      "files": [
        "todo/model.py"
      ],
      "test": "tests/test_todo.py: test_model_fields checks that Task accepts due_date and done, and serializes/deserializes correctly.",
      "check": "python -c \"from todo.model import Task; t = Task(1, 'test', True, '2023-01-01'); print(t.done, t.due_date)\"",
      "expect": "True 2023-01-01"
    },
    {
      "id": 2,
      "title": "Update storage to handle missing due_date in legacy JSON",
      "files": [
        "todo/storage.py"
      ],
      "test": "tests/test_todo.py: test_old_file_loads checks that loading a JSON without due_date defaults to None and doesn't crash.",
      "check": "python -c \"from todo import storage; t = storage.load('tests/fixtures/old.json')[0]; print(t.due_date)\"",
      "expect": "None"
    },
    {
      "id": 3,
      "title": "Update CLI to parse --due argument for add command",
      "files": [
        "todo/cli.py"
      ],
      "test": "tests/test_todo.py: test_add_with_due checks that adding a task with --due sets the due_date in the stored task.",
      "check": "python -c \"from todo import cli, storage; cli.main(['add', 'test', '--due', '2023-01-01'], 't.json'); t = storage.load('t.json')[0]; print(t.due_date)\"",
      "expect": "2023-01-01"
    },
    {
      "id": 4,
      "title": "Update CLI to implement done command",
      "files": [
        "todo/cli.py"
      ],
      "test": "tests/test_todo.py: test_done_task checks that marking a task done updates its status in storage.",
      "check": "python -c \"from todo import cli, storage; cli.main(['add', 'test'], 't.json'); cli.main(['done', '1'], 't.json'); t = storage.load('t.json')[0]; print(t.done)\"",
      "expect": "True"
    },
    {
      "id": 5,
      "title": "Update listing logic to filter and sort overdue tasks",
      "files": [
        "todo/listing.py"
      ],
      "test": "tests/test_todo.py: test_overdue_list checks that only incomplete tasks with past due dates are returned, sorted by date.",
      "check": "python -c \"from todo import listing; from todo.model import Task; tasks = [Task(1, 'a', False, '2020-01-01'), Task(2, 'b', False, '2025-01-01')]; print([t.id for t in listing.overdue(tasks)])\"",
      "expect": "[1]"
    },
    {
      "id": 6,
      "title": "Update CLI to implement overdue command",
      "files": [
        "todo/cli.py"
      ],
      "test": "tests/test_todo.py: test_overdue_command checks that the CLI prints overdue tasks correctly.",
      "check": "python -c \"from todo import cli; print(cli.main(['overdue'], 't.json'))\"",
      "expect": "1 [ ] a"
    },
    {
      "id": 7,
      "title": "Update listing render to show due dates",
      "files": [
        "todo/listing.py"
      ],
      "test": "tests/test_todo.py: test_list_with_due checks that the rendered output includes the due date after the task text.",
      "check": "python -c \"from todo import listing; from todo.model import Task; t = Task(1, 'test', False, '2023-01-01'); print(listing.render([t]))\"",
      "expect": "1 [ ] test 2023-01-01"
    },
    {
      "id": 8,
      "title": "Update CLI list command to use new render logic",
      "files": [
        "todo/cli.py"
      ],
      "test": "tests/test_todo.py: test_list_output checks that the final output format matches expectations with due dates.",
      "check": "python -c \"from todo import cli; print(cli.main(['list'], 't.json'))\"",
      "expect": "1 [ ] test 2023-01-01"
    }
  ]
}
